23	const (
24		maxTranscriptionAudioSizeBytes = 25 * MebiByte
25		maxTranscriptionFilenameLength = 255
26	)
27	
28	var supportedTranscriptionContentTypes = map[string]bool{
29		"audio/aac":    true,
30		"audio/aiff":   true,
31		"audio/flac":   true,
32		"audio/mpeg":   true,
33		"audio/mp3":    true,
34		"audio/mp4":    true,
35		"audio/mpga":   true,
36		"audio/ogg":    true,
